CREATE OR REPLACE FUNCTION public.set_video_hook(p_video uuid, p_is_vip boolean, p_text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_text text := nullif(left(btrim(coalesce(p_text, '')), 600), '');
begin
